# Rule: Fill segments of 8s with 3 when:
#   1. Between two 5s in the same row
#   2. After the last 5 if row+1 has a 5 at that column
#   3. Before the first 5 if row-1 has a 5 at that column (row 0 has no row -1, so no fill)

def make_output(input_grid):
    output = [row[:] for row in input_grid]  # Copy

    for r in range(len(input_grid)):
        5_cols = [c for c in range(len(input_grid[r])) if input_grid[r][c] == 5]

        if not 5_cols:
            continue

        # Find segments
        segments_before_first = []
        segments_between = []
        segment_after_last = []

        if 5_cols[0] > 0:
            segments_before_first.append((0, 5_cols[0] - 1))

        for i in range(len(5_cols) - 1):
            segments_between.append((5_cols[i] + 1, 5_cols[i+1] - 1))

        if 5_cols[-1] < len(input_grid[r]) - 1:
            segment_after_last.append((5_cols[-1] + 1, len(input_grid[r]) - 1))

        # Fill between two 5s (always fill)
        for seg_start, seg_end in segments_between:
            for c in range(seg_start, seg_end + 1):
                output[r][c] = 3

        # Fill segments before first 5: only if there's a 5 in row r-1 at column c
        for seg_start, seg_end in segments_before_first:
            for c in range(seg_start, seg_end + 1):
                if r > 0 and input_grid[r-1][c] == 5:
                    output[r][c] = 3

        # Fill segments after last 5: only if there's a 5 in row r+1 at column c
        for seg_start, seg_end in segment_after_last:
            for c in range(seg_start, seg_end + 1):
                if r < len(input_grid) - 1 and input_grid[r+1][c] == 5:
                    output[r][c] = 3

    return output

